// One CO's modifiers in one power state. Excludes kPowerBonus.
struct CoStateSpec {
  int16_t atk[kNumUnitTypes];  // attack %
  int16_t def[kNumUnitTypes];  // defense %
  int8_t move[kNumUnitTypes];
  int8_t range[kNumUnitTypes];  // max range, indirect units only
  int16_t terrain_atk[kNumTerrainKinds];  // by the attacker's terrain
  uint8_t atk_per_star, star_mult, luck_good, luck_bad, tower_atk, tower_def, def_vs_indirect;
  uint8_t counter, capture, cost;  // %
  bool move_cost_one;
  int16_t income_bonus;  // funds per income property
  int8_t air_fuel_per_day;
  uint8_t repair_bonus;  // internal HP
  uint8_t weather_as[kNumWeathers];  // the weather this CO's units move in
};

struct CoSpec {
  bool valid;
  const char* name;
  uint8_t cop_stars, scop_stars;  // 0 = no such power
  CoStateSpec state[3];  // none, COP, SCOP
};

